package com.magnariuk.lemonka.subs

import java.io.ByteArrayInputStream
import java.util.zip.ZipInputStream
import kotlin.test.*

class ExportTest {
    private val seps = listOf(";", ",", "and", "та")

    private val ass = listOf(
        "[Script Info]",
        "; Script generated by Aegisub",
        "Title: Frieren 01",
        "ScriptType: v4.00+",
        "Custom Key: kept",
        "",
        "[V4+ Styles]",
        "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding",
        "Style: Default,Arial,48,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,2,2,2,10,10,10,1",
        "",
        "[Fonts]",
        "fontname: custom.ttf",
        "",
        "[Events]",
        "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text",
        "Comment: 0,0:00:00.00,0:00:01.00,Default,Note,0,0,0,,коментар",
        "Dialogue: 0,0:00:01.50,0:00:02.00,Default,Fern,0,0,0,,Добрий день, пане Штарк",
        "Dialogue: 0,0:00:02.00,0:00:03.25,Default,Stark,0,0,0,,{\\an8}Привіт\\Nдругий рядок",
        "Dialogue: 0,0:00:03.00,0:00:04.00,Default,Fern та Stark,0,0,0,,Разом!",
        "Dialogue: 0,1:02:03.04,1:02:05.00,Default,Frieren,0,0,0,,Довго",
    ).joinToString("\r\n")

    @Test
    fun `filter keeps everything except other characters' dialogue, byte for byte`() {
        val out = AssEditor(ass).filterTo(setOf("Fern"), seps)!!
        val expected = ass.lines().filter { !it.startsWith("Dialogue:") || "Fern" in it }
            .joinToString("\r\n")
            .replace(",Fern та Stark,", ",Fern,") // shared line keeps only the selected name
        assertEquals(expected, out)
        assertContains(out, "[Fonts]"); assertContains(out, "Custom Key: kept"); assertContains(out, "Comment: 0,0:00:00.00,0:00:01.00,Default,Note")
        assertTrue("\r\n" in out, "line endings preserved")
    }

    @Test
    fun `characters only in shared lines still get a file`() {
        val text = ass.replace("Dialogue: 0,0:00:02.00,0:00:03.25,Default,Stark,", "Dialogue: 0,0:00:02.00,0:00:03.25,Default,Fern,")
        assertNotNull(AssEditor(text).filterTo(setOf("Stark"), seps))
        assertNull(AssEditor(ass).filterTo(setOf("Nobody"), seps))
    }

    @Test
    fun `rename does not touch the original and maps every name`() {
        val editor = AssEditor(ass)
        val renamed = editor.renameToActors(mapOf("Fern" to "Олена", "Stark" to "Максим"), seps)
        assertContains(renamed, ",Default,Олена та Максим,")
        assertContains(renamed, ",Default,Frieren,") // unknown stays
        // Running a filter afterwards still sees the original names (the old code mutated them)
        assertNotNull(editor.filterTo(setOf("Fern"), seps))
    }

    @Test
    fun `srt timings use milliseconds`() {
        assertEquals("00:00:01,500", SrtWriter.time("0:00:01.50"))
        assertEquals("01:02:03,040", SrtWriter.time("1:02:03.04"))
        assertEquals("00:00:03,250", SrtWriter.time("0:00:03.25"))
    }

    @Test
    fun `srt export`() {
        val parsed = AssParser.parse(ass.byteInputStream(), "a.ass")
        val srt = SrtWriter.fromAss(parsed, setOf("Stark"), seps)!!
        assertEquals(
            "1\n00:00:00,000 --> 00:00:00,001\n \n\n" +
                "2\n00:00:02,000 --> 00:00:03,250\n[Stark]: Привіт\nдругий рядок\n\n" +
                "3\n00:00:03,000 --> 00:00:04,000\n[Stark]: Разом!\n",
            srt,
        )
    }

    @Test
    fun `exporter - by actor, by character, renamed, zip`() {
        val ex = SubtitleExporter("Frieren 01.ass", ass, seps)
        val mapping = mapOf("Олена" to listOf("Fern", "Frieren"), "Максим" to listOf("Stark"), "Без ролей" to emptyList())

        val byActor = ex.export(ExportKind.ByActor, SubFormat.Ass, mapping)
        assertEquals(listOf("Олена.ass", "Максим.ass"), byActor.map { it.name }) // actor without lines → no file

        val byChar = ex.export(ExportKind.ByCharacter, SubFormat.Srt, mapping)
        assertEquals(listOf("Fern.srt", "Frieren.srt", "Stark.srt"), byChar.map { it.name })

        val renamed = ex.export(ExportKind.Renamed, SubFormat.Srt, mapping).single()
        assertEquals("Frieren 01_renamed.ass", renamed.name)

        val zip = SubtitleExporter.zip(byActor + byActor.first())
        val names = ZipInputStream(ByteArrayInputStream(zip)).use { z -> generateSequence { z.nextEntry?.name }.toList() }
        assertEquals(listOf("Олена.ass", "Максим.ass", "Олена (2).ass"), names)
    }
}
